/*
 * asknode/test/test_asknode_data.c - the ASKNODE module block (source-esg8)
 *
 * Generated by: Claude Opus 5.5
 *
 * asknode/asknode_data.c is #included, so the object under test is the real
 * ASKNODE_$DATA (map "D E82408 ASKNODE size = 20") with the image's contents
 * (`gsk read 0xE82408 0x20`):
 *
 *   +0x00  00 10 00 02 00 02 80 31  ff ff 00 00 ff ff 00 00
 *   +0x10  00 00 00 00 00 00 00 00  00 00 00 00 00 00 00 03
 *
 * Checked: the block address and size, the template at (A5) and
 * protocol_version at (0x1e,A5) overlaying the template's last word, and the
 * initial contents.
 */

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* ==========================================================================
 * Test framework
 * ========================================================================== */

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

#include "asknode/asknode_internal.h"
#include "../asknode_data.c"

#define OFF(field) ((size_t)((uint8_t *)&(field) - (uint8_t *)&ASKNODE_$DATA))

/* ==========================================================================
 * Tests
 * ========================================================================== */

TEST(block_address_and_size)
{
    ASSERT_EQ(0x00E82408u, MODULE_DATA_ADDR(ASKNODE_$DATA));
    ASSERT_EQ(0x20, sizeof(ASKNODE_$DATA));
    ASSERT_EQ(ASKNODE_$DATA_SIZE, sizeof(asknode_$data_t));
}

/* "lea (A5),A0" (0x00E656DC) and "cmpi.w #0x3,(0x1e,A5)" (0x00E657BC). */
TEST(offsets)
{
    ASSERT_EQ(0x00, OFF(ASKNODE_$DATA.pkt_info));
    ASSERT_EQ(0x1E, OFF(ASKNODE_$DATA.protocol_version));
    ASSERT_EQ(OFF(ASKNODE_$DATA.pkt_info.pad_1e),
              OFF(ASKNODE_$DATA.protocol_version));
}

TEST(initial_contents_match_the_image)
{
    int i;

    ASSERT_EQ(0x0010, ASKNODE_$DATA.pkt_info.flags);
    ASSERT_EQ(2, ASKNODE_$DATA.pkt_info.routing_type);
    ASSERT_EQ(2, ASKNODE_$DATA.pkt_info.addr_type);
    ASSERT_EQ(0x8031, ASKNODE_$DATA.pkt_info.protocol);
    ASSERT_EQ(0xFFFF, ASKNODE_$DATA.pkt_info.retry_limit);
    ASSERT_EQ(0, ASKNODE_$DATA.pkt_info.field_0a);
    ASSERT_EQ(0xFFFF, ASKNODE_$DATA.pkt_info.field_0c);
    for (i = 0; i < 16; i++) {
        ASSERT_EQ(0, ASKNODE_$DATA.pkt_info.addr[i]);
    }
    ASSERT_EQ(3, ASKNODE_$DATA.protocol_version);   /* 0x00E82426: 00 03 */
}

/* The 30-byte copy every sender makes (7 longwords + 1 word) stops short of
 * protocol_version. */
TEST(template_copy_excludes_the_version_word)
{
    pkt_$info_t copy;
    const uint32_t *src = (const uint32_t *)&ASKNODE_$DATA.pkt_info;
    uint32_t *dst = (uint32_t *)&copy;
    int i;

    memset(&copy, 0x5A, sizeof(copy));
    for (i = 0; i < 7; i++) *dst++ = *src++;
    *(uint16_t *)dst = *(const uint16_t *)src;

    ASSERT_EQ(0x0010, copy.flags);
    ASSERT_EQ(0x8031, copy.protocol);
    ASSERT_EQ(0xFFFF, copy.field_0c);
    ASSERT_EQ(0x5A5A, copy.pad_1e);
}

int main(void)
{
    printf("ASKNODE module data tests\n");

    RUN_TEST(block_address_and_size);
    RUN_TEST(offsets);
    RUN_TEST(initial_contents_match_the_image);
    RUN_TEST(template_copy_excludes_the_version_word);

    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed != 0;
}
